# End-to-end check of the Windows self-install helper against a real publish.
#
# Publishes two real self-contained win-x64 builds (old and new version), keeps
# the old one as the "installation" source, rebuilds the new one with the same
# top-level layout as the release zip and runs the WindowsSelfInstallTests
# integration test. The test starts the real exe, runs the real PowerShell
# helper generated by UpdateInstaller, checks that the helper waits for the app
# PID, replaces the folder and restores it when the new exe cannot start.
#
# Usage (Windows only, from the repository root):
#   pwsh scripts/self-install-windows.ps1
#   pwsh scripts/self-install-windows.ps1 -Root C:\temp\self-install -Keep
#
# Without -Keep the script deletes its working tree on success. A failed run
# keeps the tree so the helper log and the evidence file can be inspected.

[CmdletBinding()]
param(
    [string]$Root,
    [string]$OldVersion = "0.1.0",
    [string]$NewVersion = "0.2.0",
    [switch]$Keep
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

if ($env:OS -ne "Windows_NT") {
    throw "The Windows self-install test only runs on Windows."
}
if (-not (Get-Command dotnet -ErrorAction SilentlyContinue)) {
    throw "The .NET SDK (dotnet) is not on PATH."
}

$repo = Split-Path -Parent $PSScriptRoot
$markerFile = "self-install-marker.txt"
$oldMarker = "old-$OldVersion"
$newMarker = "new-$NewVersion"
$payloadName = "InfraOrgIT-Desktop-$NewVersion-win-x64"

if (-not $Root) {
    $Root = Join-Path ([IO.Path]::GetTempPath()) (
        "infraorgit-self-install-" + [Guid]::NewGuid().ToString("N"))
}
$Root = [IO.Path]::GetFullPath($Root)
if (Test-Path -LiteralPath $Root) {
    Remove-Item -LiteralPath $Root -Recurse -Force
}
New-Item -ItemType Directory -Path $Root -Force | Out-Null

function Invoke-Publish {
    param([string]$Version, [string]$Output)

    & dotnet publish (Join-Path $repo "src/InfraOrgIt.Desktop/InfraOrgIt.Desktop.csproj") `
        -c Release -r win-x64 --self-contained true `
        -p:PublishSingleFile=true `
        -p:IncludeNativeLibrariesForSelfExtract=true `
        -p:Version=$Version `
        -o $Output
    if ($LASTEXITCODE -ne 0) {
        throw "dotnet publish failed for version $Version (exit $LASTEXITCODE)."
    }
    if (-not (Test-Path -LiteralPath (Join-Path $Output "InfraOrgIt.Desktop.exe") -PathType Leaf)) {
        throw "The publish output has no InfraOrgIt.Desktop.exe: $Output"
    }
}

$succeeded = $false
$testExit = 1
try {
    $oldPublish = Join-Path $Root "publish-old"
    $newPublish = Join-Path $Root "publish-new"

    Write-Host "Publishing win-x64 $OldVersion (old) and $NewVersion (new)..."
    Invoke-Publish -Version $OldVersion -Output $oldPublish
    Set-Content -LiteralPath (Join-Path $oldPublish $markerFile) `
        -Value $oldMarker -NoNewline -Encoding utf8
    Invoke-Publish -Version $NewVersion -Output $newPublish
    Set-Content -LiteralPath (Join-Path $newPublish $markerFile) `
        -Value $newMarker -NoNewline -Encoding utf8

    # Same top-level layout as dist/InfraOrgIT-Desktop-<version>-win-x64.zip
    # produced by scripts/publish.sh.
    $payload = Join-Path (Join-Path $Root "payload") $payloadName
    New-Item -ItemType Directory -Path $payload -Force | Out-Null
    Copy-Item -Path (Join-Path $newPublish "*") -Destination $payload `
        -Recurse -Force

    $archive = Join-Path $Root "$payloadName.zip"
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [IO.Compression.ZipFile]::CreateFromDirectory(
        $payload, $archive, [IO.Compression.CompressionLevel]::Optimal, $true)

    $zip = [IO.Compression.ZipFile]::OpenRead($archive)
    try {
        $entries = @($zip.Entries | ForEach-Object { $_.FullName.Replace('\', '/') })
        $roots = @($entries | ForEach-Object { ($_ -split '/')[0] } | Sort-Object -Unique)
        if ($roots.Count -ne 1 -or $roots[0] -ne $payloadName) {
            throw "Unexpected update zip layout (roots: $($roots -join ', '))."
        }
        if ($entries -notcontains "$payloadName/InfraOrgIt.Desktop.exe") {
            throw "The update zip has no $payloadName/InfraOrgIt.Desktop.exe entry."
        }
    }
    finally {
        $zip.Dispose()
    }

    $evidence = Join-Path $Root "evidence.txt"
    $env:INFRAORGIT_SELF_INSTALL_OLD_PUBLISH = $oldPublish
    $env:INFRAORGIT_SELF_INSTALL_ARCHIVE = $archive
    $env:INFRAORGIT_SELF_INSTALL_OLD_MARKER = $oldMarker
    $env:INFRAORGIT_SELF_INSTALL_NEW_MARKER = $newMarker
    $env:INFRAORGIT_SELF_INSTALL_EVIDENCE = $evidence

    Write-Host "Running WindowsSelfInstallTests..."
    & dotnet test (Join-Path $repo "InfraOrgITDesktop.slnx") `
        --filter "FullyQualifiedName~WindowsSelfInstallTests" `
        --logger "console;verbosity=detailed"
    $testExit = $LASTEXITCODE
    $succeeded = $testExit -eq 0

    Write-Host ""
    Write-Host "Self-install evidence:"
    Write-Host "  old publish: $oldPublish"
    Write-Host "  update zip : $archive"
    Write-Host "  markers    : $oldMarker -> $newMarker"
    if (Test-Path -LiteralPath $evidence) {
        Get-Content -LiteralPath $evidence | ForEach-Object { Write-Host "  $_" }
    }
    Write-Host ""

    if (-not $succeeded) {
        throw "Windows self-install test failed (exit $testExit)."
    }
}
finally {
    foreach ($name in @(
            "INFRAORGIT_SELF_INSTALL_OLD_PUBLISH",
            "INFRAORGIT_SELF_INSTALL_ARCHIVE",
            "INFRAORGIT_SELF_INSTALL_OLD_MARKER",
            "INFRAORGIT_SELF_INSTALL_NEW_MARKER",
            "INFRAORGIT_SELF_INSTALL_EVIDENCE")) {
        Remove-Item -LiteralPath "Env:\$name" -ErrorAction SilentlyContinue
    }

    if ($Keep -or -not $succeeded) {
        Write-Host "Self-install workspace kept at $Root"
    }
    else {
        Remove-Item -LiteralPath $Root -Recurse -Force -ErrorAction SilentlyContinue
    }
}
